// v0.35 flight manoeuvres (TR: UH-1 Uçuş Hareketleri). Exactly the list asked for, in that order, plus the tactical
// items (ilerleme teknikleri, gizlenme–açığa çıkma, arazi uçuşu, kol uçuşu). Each manoeuvre is a list of segments flown
// by the program-flight model; "say" items are the narration from the book (görev, başlangıç esasları, anlatım) with a
// cockpit target, decisions (karar vererek ilerle) change the segment so the consequence of a technique is flown.
// Every manoeuvre carries its flight area (meydan / arazi / dağlık / orman) and, on the airfield, its start point.
import {terrainHeight,surfaceProfile,obstacleClearance,obstacleTopNear,RUNWAY,POWER_LINES,MT_HILLS,TEPE_SITES,treesNear,buildingsNear,wireTopNear} from './terrain-data.js';
import {REAL_AREAS} from './real-area.js';
import {slopeDeg,bestSpotNear} from './landing-zone.js';
const KT=1852/3600,FT=.3048,G=9.81,R=Math.PI/180;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),wrap=a=>Math.atan2(Math.sin(a),Math.cos(a));
const opt=(id,label,text,set={},risk=false,note='')=>({id,label,text,set,risk,note});
const D=(id,title,options,reference)=>({decision:{id,title,options,reference:reference??options[0].id}});
const say=(title,text,target,set)=>({t:'say',title,text,...(target?{target}:{}),...(set?{set}:{})});
const sw=(title,text,target,extra={})=>({t:'sw',title,text,target,dur:extra.dur??4,...extra});
// airfield (Güvercinlik) runway frame: along the runway (landing direction 065°), across = right of it
const RWH=RUNWAY.heading,RWD=Math.round(RWH/R),TD=-450;
export const rwPoint=(along,across=0)=>({x:Math.round(along*Math.sin(RWH)+across*Math.cos(RWH)),z:Math.round(-along*Math.cos(RWH)+across*Math.sin(RWH))});
/* the program flight backs the start up by 4 s of flight and the task is then read for 4 s: (along, across) is where the first segment starts */
/* v0.35.9 helikopter iniş panelleri — Güvercinlik Meydan Talimatı md.2-c (060 istikametine göre 1…4; 1. panel
   K39°56.27' D032°44.65' … 4. panel K39°56.18' D032°44.41', ≈127 m ara) — panel hattı yolu üzerinde (OSM "Helicopter Panels") */
export const PANEL_ALONG=[469,343,216,90],PANEL_ACROSS=-159; /* v0.37 OSM panel hattı pist çerçevesinde −159 m (talimat ≈ −157 m) */
/* meydan turu dönüş noktaları (talimat 5-11): yan bacak kesişimi, rüzgâraltına dönüş, esas bacak kesişimi, son yaklaşmaya dönüş */
const PT={A:[1803,-235],B:[1741,830],C:[-1369,920],D:[-1372,-176]};
/* v0.39 tırmanış (kalkış) bacağı yarıya indirildi: yan bacak kesişimi pist sonundan ≈130 m ileride */
const PT2={A:[1136,-235],B:[1074,830],D:[-705,-176],C:[-702,920]};
const PANELP=n=>({along:PANEL_ALONG[n-1],across:PANEL_ACROSS});
const AFP=(n,h=0,v=0,rev=false)=>({h,v,area:'airfield',...rwPoint(PANEL_ALONG[n-1],PANEL_ACROSS),hdg:rev?(RWD+180)%360:RWD,panel:n});
const AF=(h,v,along,across=0,dh=0)=>{const b=0;return {h,v,area:'airfield',...rwPoint(along+b*Math.cos(dh*R),across+b*Math.sin(dh*R)),hdg:(RWD+dh+360)%360};};
